stepxmp.pre:
@supports selector(chapter > title) and (display: block) {
    chapter > title { display: block; }
}

@supports-condition --basic-layout {
    display: block;
    color: navy;
}

@supports (--basic-layout) {
    chapter { display: block; }
}

@when media(overflow-block: paged) and supports(color: navy) {
    title { color: navy; }
}

@when supports(color: navy) {
    title { color: navy; }
} @else supports(color: black) {
    title { color: black; }
} @else {
    title { color: inherit; }
}

@layer reset, base, theme;

@layer theme {
    title { color: navy; }
}
